# Rust dylib consumed dynamically by Rust crates (e.g. http_ani via
# --extern + NEEDED). Rust cross-crate dynamic linkage resolves arbitrary
# pub/cxxbridge symbols at runtime, so the whole Rust ABI surface is kept:
#   - _RN*: all v0-mangled Rust symbols (own crate + cxx runtime crate),
#     immune to crate-hash changes across rebuilds
#   - cxxbridge1$* / OHOS$*: cxx bridge C-style symbols
#   - rust_metadata_*: rustc crate metadata for downstream --extern
# Only non-Rust leaks (C symbols, std/gcov style leftovers) are hidden.

{
  global:
    _RN*;
    _ZN*11netstack_rs*;
    _ZNK*11netstack_rs*;
    cxxbridge1$*;
    OHOS$*;
    rust_metadata*;
  local:
    *;
};
